<?php require_once __DIR__.'/auth.php'; $title='Bookings'; include 'admin-head.php'; include 'sidebar.php'; include 'topbar.php'; ?><main class="main"><?php $items=read_data('bookings');if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='delete'){$id=(int)$_POST['id'];$items=array_values(array_filter($items,fn($x)=>(int)$x['id']!==$id));write_data('bookings',$items);}else{$id=(int)$_POST['id'];foreach($items as &$x)if((int)$x['id']===$id)$x['status']=$_POST['status']??'New';unset($x);}redirect('booking.php');}?>
<div class="card shadow-sm border-0"><div class="card-header bg-white d-flex justify-content-between"><h5 class="mb-0 fw-bold">Customer Bookings</h5><span class="badge bg-success"><?=count($items)?></span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Customer</th><th>Package</th><th>Travel</th><th>Guests</th><th>Status</th><th></th></tr></thead><tbody><?php foreach(array_reverse($items) as $b): ?><tr><td><strong><?=e($b['name'])?></strong><br><small><?=e($b['email'])?><br><?=e($b['mobile'])?></small></td><td><?=e($b['package_name'])?><br><small><?=e($b['country'])?></small></td><td><?=e($b['arrival_date'])?><br>→ <?=e($b['departure_date'])?></td><td>Adults: <?=e($b['adults'])?><br>Children: <?=e($b['children'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$b['id']?>"><select name="status" class="form-select form-select-sm" onchange="this.form.submit()"><?php foreach(['New','Contacted','Confirmed','Completed','Cancelled'] as $st): ?><option <?=$st===($b['status']??'New')?'selected':''?>><?=$st?></option><?php endforeach;?></select></form></td><td><form method="post" onsubmit="return confirm('Delete booking?')"><input type="hidden" name="id" value="<?=$b['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-outline-danger"><i class="fa-solid fa-trash"></i></button></form></td></tr><tr class="table-light"><td colspan="6"><strong>Message:</strong> <?=e($b['message']??'')?></td></tr><?php endforeach;?><?php if(!$items): ?><tr><td colspan="6" class="text-center py-5 text-muted">No bookings yet.</td></tr><?php endif;?></tbody></table></div></div><?php include 'admin-foot.php'; ?>